S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os,wave,math as m;q=sys.argv[1];T=max(1,int(sys.argv[2]));k=sys.argv[3];S=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));C=lambda s:[w for w in("".join(c.lower()if c.isalnum()else" "for c in s).split())if w];R=C(q);W=R or["void"];qn=" ".join(R);g=sum((b+1)*257**i for i,b in enumerate(J([qn,T,k,"song"]).encode()));kv=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));sr=sum((i+1)*(b+1)for i,b in enumerate(open(S,"rb").read()if os.path.exists(S)else b""))%10**18;b=min(T,10);N=(1<<(b+1))-1;M=997+g%97;F=lambda j:(g+sr*j+j*j+kv)%M;O=min((F(j),j)for j in range(N));ttl="Zero Origin %s V%s"%(W[0].title(),k);ly="A.lyr";wa="A.wav";mp="A.mp3";open(ly,"w").write(ttl+"\n"+qn[:32]+"\nvariant "+k+" returns\n");n=8000*T;f=110+(O[1]+kv)%220;Y=b"".join(int(.35*m.sin(6.28*f*i/8000)*min(1,i/800)*min(1,(n-i)/800)*30000).to_bytes(2,"little",signed=True)for i in range(n));w=wave.open(wa,"wb");w.setparams((1,2,8000,0,"NONE",""));w.writeframes(Y);w.close();os.system("ffmpeg -y -loglevel error -i A.wav A.mp3 >/dev/null 2>&1");ok=int(os.path.exists(mp));V=int(len(R)>0 and qn==" ".join(R)and O==min((F(j),j)for j in range(N))and os.path.getsize(wa)>44 and ttl=="Zero Origin %s V%s"%(W[0].title(),k));D={"P":"RMZANS2K","NL":"RMZ-NL/1","Q_RAW":q,"Q_NORM":qn,"LANG":"en"if q.isascii()else"mixed","TOKENS":R,"INTENT":"song","TT_NL":"z0;QRaw;QNorm;TZC;NZO;MMLC","TT_CLASS":"TZC=noise;NZO=song-use","MML_TARGET":"RMZ-MML/1","MML":"RMZ-MML/1","GRAM":"NL TOK TT MML WAV CERT","VERIFY":"recalc NL/G/OPT/TITLE/WAV","REJECT":"V=0","SELF":sr,"ORIGIN":sr,"DELTA0":1,"VARIANT":k,"BND":b,"ENUM":N,"OPT":O,"TITLE":ttl,"TITLE_CERT":V,"TM":"qRaw>qNorm>qLex>qTT>qMML>qOpt>qTitle>qWAV>qVerify>qZE","TT":"z0;D0;TZC;NZO;outC","PCC":V,"L":ly,"W":wa,"MP3":[mp,ok],"ZE":V,"Bd":"bounded NL-to-MML;not full NL"};open("A.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"NL":D["NL"],"TITLE":ttl,"V":V,"PCC":V,"ZE":V,"mp3_ok":ok,"cert":"A.clcert","bytes":"<2048